// arbitrage_checker.cpp#include "arbitrage_checker.hpp"arbitrage_checker::arbitrage_checker(tick_handler& spot_ticks, tick_handler& future_ticks, int64_t qty, const std::string table_name, db_connection& db_conn) :    spot_ticks_(spot_ticks),    future_ticks_(future_ticks),    qty_(qty),    table_name_(table_name),    db_conn_(db_conn){}void arbitrage_checker::check_buy_spot_sell_future(){    int64_t spot_ask   = spot_ticks_.get_ask_price();    int64_t future_bid = future_ticks_.get_bid_price();    int64_t spread = future_bid - spot_ask;    if (is_profitable(spread, spot_ask, qty_)) {        db_conn_.insert_trade(table_name_, future_bid, spot_ask, spread, true);    }}void arbitrage_checker::check_sell_spot_buy_future(){    int64_t spot_bid   = spot_ticks_.get_bid_price();    int64_t future_ask = future_ticks_.get_ask_price();    int64_t spread = spot_bid - future_ask;    if (is_profitable(spread, spot_bid, qty_)) {        db_conn_.insert_trade(table_name_, spot_bid, future_ask, spread, false);    }}void arbitrage_checker::check_for_arbitrage(){    check_buy_spot_sell_future();    check_sell_spot_buy_future();}